import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association to outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for driver selection
        y1 = feats.x[feats.y==1, i]
        y0 = feats.x[feats.y==0, i]
        tstat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        pval = stats.ttest_ind(y1, y0, equal_var=False)[1]
        auc = 0.5 + 0.5 * (np.mean(y1) - np.mean(y0)) / (np.std(y1) + np.std(y0) + 1e-8)
        effects.append((fid, abs(tstat), pval, auc))

    effects.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates
    candidates = [f for f, _, _, _ in effects[:20]]

    # Check for product terms among highly correlated pairs
    correlations = {}
    for i, f1 in enumerate(candidates):
        for j, f2 in enumerate(candidates[i+1:], i+1):
            if f1 in feats.ids and f2 in feats.ids:
                col1 = feats.column(f1)
                col2 = feats.column(f2)
                corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
                if abs(corr) >= 0.6:
                    correlations[(f1, f2)] = corr

    # Look for product terms with highest effect size
    best_product = None
    best_effect = 0

    for (f1, f2), corr in correlations.items():
        col1 = feats.column(f1)
        col2 = feats.column(f2)
        product = feats.x[:, col1] * feats.x[:, col2]

        y1 = product[feats.y==1]
        y0 = product[feats.y==0]
        tstat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        effect = abs(tstat)

        if effect > best_effect:
            best_effect = effect
            best_product = (f1, f2)

    if best_product:
        return Design(
            drivers=(best_product[0],),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0}
        )

    # If no strong product, use top features
    drivers = tuple(f for f, _, _, _ in effects[:MAX_DRIVERS])
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    return Design(
        drivers=drivers,
        columns=drivers,
        products=(),
        loadings={f: 1.0 for f in drivers}
    )

